hcl:
terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Generates a random suffix to ensure globally unique bucket naming
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "google_storage_bucket" "storage_bucket" {
  name     = "bkt-storage-${random_id_bucket_suffix.hex}"
  location = "asia-south1"

  # Access control and security configurations
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  # Explicit retention mechanism required by organizational policy
  versioning {
    enabled = true
  }

  # Mandatory organizational labels
  labels = {
    environment = "prod"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "europe-west1"
}

resource "google_storage_bucket" "coldline_bucket" {
  name                        = "coldline-storage-europe-west1-bucket"
  location                    = "europe-west1"
  storage_class               = "COLDLINE"
  uniform_bucket_level_access = true

  # Policy requirement: storage resources must declare an explicit retention mechanism
  versioning {
    enabled = true
  }

  # Policy requirement: every resource must carry a labels map with at least environment
  labels = {
    environment = "prod"
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

resource "google_storage_bucket" "invoices_archive" {
  name                        = "acme-invoices-archive"
  location                    = "asia-south1"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  versioning {
    enabled = true
  }

  labels = {
    environment = "prod"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Cloud Storage bucket with lifecycle transition to NEARLINE after 30 days
resource "google_storage_bucket" "lifecycle_bucket" {
  name                        = "org-storage-nearline-archive-bucket"
  location                    = "asia-south1"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  labels = {
    environment = "prod"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Service account for reading objects from the storage bucket
resource "google_service_account" "reader" {
  account_id   = "storage-object-reader"
  display_name = "Storage Object Reader Service Account"
}

# Private Cloud Storage bucket adhering to organisational policies
resource "google_storage_bucket" "private_bucket" {
  name                        = "private-data-bucket-asia-south1"
  location                    = "asia-south1"
  uniform_bucket_level_access = true

  # Organisational policy: storage resources must declare an explicit retention mechanism
  versioning {
    enabled = true
  }

  # Organisational policy: mandatory labels tracking environment
  labels = {
    environment = "dev"
  }
}

# Grant read-only object access to the service account for the specific bucket
resource "google_storage_bucket_iam_member" "reader_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.reader.email}"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Cloud Storage bucket that automatically deletes objects 90 days after creation
resource "google_storage_bucket" "auto_delete_bucket" {
  name                        = "org-bucket-auto-delete-90-days"
  location                    = "asia-south1"
  uniform_bucket_level_access = true

  labels = {
    environment = "prod"
  }

  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# PostgreSQL 15 Cloud SQL Instance
resource "google_sql_database_instance" "postgres" {
  name                = "prod-postgres-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Mandatory organizational labels
    user_labels = {
      environment = "prod"
    }

    # Backup retention configuration
    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    # Restrict public access per organizational security policy
    ip_configuration {
      ipv4_enabled = false
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated VPC network for private database communication
resource "google_compute_network" "default" {
  name                    = "mysql-vpc-network"
  auto_create_subnetworks = false
}

# Reserve an internal IP range for private services access (Cloud SQL VPC peering)
resource "google_compute_global_address" "private_ip_allocation" {
  name          = "mysql-private-ip-allocation"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.default.id
}

# Establish private VPC peering with Google Services
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.default.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_allocation.name]
}

# Highly available MySQL 8.0 Cloud SQL instance
resource "google_sql_database_instance" "mysql_ha" {
  name                = "mysql-ha-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Automated backups with binary logging enabled (required for MySQL HA/PITR)
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    # Restrict ingress: disable public IPv4 and attach to private VPC
    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.default.id
    }

    user_labels = {
      environment = "prod"
    }
  }

  depends_on = [
    google_service_networking_connection.private_vpc_connection
  ]
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
