provider "google" {
  region = "asia-south1"
}

# Dedicated VPC network for private database access
resource "google_compute_network" "private_network" {
  name                    = "sql-private-vpc"
  auto_create_subnetworks = false
}

# Subnet for general workloads in the mandatory region
resource "google_compute_subnetwork" "subnet" {
  name          = "sql-private-subnet"
  ip_cidr_range = "10.0.0.0/24"
  region        = "asia-south1"
  network       = google_compute_network.private_network.id
}

# Reserved internal IP address range for Private Services Access (Cloud SQL)
resource "google_compute_global_address" "private_ip_address" {
  name          = "private-ip-allocation"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.private_network.id
}

# Service Networking Connection for Cloud SQL private IP connectivity
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.private_network.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_address.name]
}

# Cloud SQL PostgreSQL Instance
resource "google_sql_database_instance" "postgres" {
  name                = "postgres-primary-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.private_network.id
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    user_labels = {
      environment = "prod"
    }
  }

  depends_on = [google_service_networking_connection.private_vpc_connection]
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "private_network_id" {
  description = "The self_link or ID of the VPC network to which the Cloud SQL instance connects via Private Service Access."
  type        = string
}

variable "db_password" {
  description = "Password for the database application user."
  type        = string
  sensitive   = true
}

resource "google_sql_database_instance" "postgres" {
  name                = "app-postgres-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    user_labels = {
      environment = "prod"
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network_id
    }
  }
}

resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.postgres.name
}

resource "google_sql_user" "appuser" {
  name     = "appuser"
  instance = google_sql_database_instance.postgres.name
