terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

data "google_project" "current" {}

# Custom service account with least privilege for cluster nodes
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Grant minimal permissions required by GKE nodes
resource "google_project_iam_member" "node_roles" {
  for_each = toset([
    "roles/logging.logWriter",
    "roles/monitoring.metricWriter",
    "roles/monitoring.viewer"
  ])

  project = data.google_project.current.project_id
  role    = each.key
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# Regional GKE Cluster in asia-south1
resource "google_container_cluster" "primary" {
  name     = "asia-south1-gke-cluster"
  location = "asia-south1"

  # Delete the default node pool upon creation to manage separately
  remove_default_node_pool = true
  initial_node_count       = 1

  # Mandatory organizational policy labels
  resource_labels = {
    environment = "prod"
  }
}

# Separately managed node pool with 3 e2-standard-4 nodes
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.name
  node_count = 3

  node_config {
    machine_type    = "e2-standard-4"
    service_account = google_service_account.gke_nodes.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "prod"
    }
  }
}

# Terraform configuration for a Cloud SQL PostgreSQL instance with point-in-time recovery

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "private_network_id" {
  type        = string
  description = "The full resource name or self-link of the VPC network to which the instance will be connected via private IP."
  default     = "projects/my-project/global/networks/shared-vpc"
}

resource "google_sql_database_instance" "postgres" {
  name                = "postgres-instance-prod"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
      transaction_log_retention_days = 7
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network_id
    }

    user_labels = {
      environment = "prod"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = "asia-south1"
}

variable "project_id" {
  type        = string
  description = "The GCP project ID"
}

variable "environment" {
  type        = string
  description = "The deployment environment"
  default     = "prod"
}

# Dedicated VPC network for the GKE cluster
resource "google_compute_network" "gke_network" {
  name                    = "gke-network"
  auto_create_subnetworks = false
}

# Subnet configured with secondary IP ranges for GKE pods and services
resource "google_compute_subnetwork" "gke_subnetwork" {
  name                     = "gke-subnet-asia-south1"
  ip_cidr_range            = "10.10.0.0/20"
  region                   = "asia-south1"
  network                  = google_compute_network.gke_network.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pod-ranges"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "service-ranges"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# Dedicated least-privilege service account for GKE nodes
resource "google_service_account" "gke_node_sa" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Minimal IAM roles required for GKE nodes (least-privilege)
resource "google_project_iam_member" "node_log_writer" {
  project = var.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.gke_node_sa.email}"
}

resource "google_project_iam_member" "node_metric_writer" {
  project = var.project_id
  role    = "roles/monitoring.metricWriter"
  member  = "serviceAccount:${google_service_account.gke_node_sa.email}"
}

resource "google_project_iam_member" "node_monitoring_viewer" {
  project = var.project_id
  role    = "roles/monitoring.viewer"
  member  = "serviceAccount:${google_service_account.gke_node_sa.email}"
}

# Regional private GKE cluster with Workload Identity enabled
resource "google_container_cluster" "primary" {
  name     = "primary-cluster"
  location = "asia-south1"

  network    = google_compute_network.gke_network.id
  subnetwork = google_compute_subnetwork.gke_subnetwork.id

  # Remove the default node pool to manage nodes using separate resource
  remove_default_node_pool = true
  initial_node_count       = 1

  # IP allocation policy required for VPC-native clusters and alias IPs
  ip_allocation_policy {
    cluster_secondary_range_name  = "pod-ranges"
    services_secondary_range_name = "service-ranges"
  }

  # Private cluster configuration (nodes have private IPs only)
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Workload Identity configuration for workload-to-GCP authentication
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  release_channel {
    channel = "REGULAR"
  }

  resource_labels = {
    environment = var.environment
  }

  deletion_protection = true
}

# Separately defined primary node pool
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.name
  node_count = 1

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.gke_node_sa.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = var.environment
    }

    # Enable GKE Workload Identity on the node pool
    workload_metadata_config {
      mode = "GKE_METADATA"
    }
  }

  depends_on = [
    google_project_iam_member.node_log_writer,
    google_project_iam_member.node_metric_writer,
    google_project_iam_member.node_monitoring_viewer
  ]
}

# Terraform configuration for a GKE Autopilot cluster in asia-south1
# Conforms to organizational security and naming policies.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated VPC for GKE
resource "google_compute_network" "gke_vpc" {
  name                    = "gke-autopilot-vpc"
  auto_create_subnetworks = false
}

# Dedicated subnet with secondary IP ranges for pods and services
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-autopilot-subnet"
  region                   = "asia-south1"
  network                  = google_compute_network.gke_vpc.id
  ip_cidr_range            = "10.10.0.0/20"
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pod-ranges"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "service-ranges"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# GKE Autopilot Cluster
resource "google_container_cluster" "primary" {
  name             = "autopilot-cluster-asia-south1"
  location         = "asia-south1"
  enable_autopilot = true

  network    = google_compute_network.gke_vpc.name
  subnetwork = google_compute_subnetwork.gke_subnet.name

  ip_allocation_policy {
    cluster_secondary_range_name  = "pod-ranges"
    services_secondary_range_name = "service-ranges"
  }

  # Mandatory organization policy labels
  resource_labels = {
    environment = "prod"
  }
}

