resource "google_compute_network" "custom_vpc" {
  name                    = "custom-vpc"
  auto_create_subnetworks = false
  description             = "Custom VPC network"
}

# Subnetwork in asia-south1 using the 10.10.0.0/24 CIDR range
# Note: google_compute_subnetwork does not support labels in the GCP Compute Engine API.
resource "google_compute_subnetwork" "custom_subnet" {
  name                     = "custom-subnet-asia-south1"
  ip_cidr_range            = "10.10.0.0/24"
  region                   = "asia-south1"
  network                  = google_compute_network.custom_vpc.id
  private_ip_google_access = true
  description              = "Custom subnetwork in asia-south1 with Private Google Access enabled"
}

# Terraform configuration for allowing inbound TCP port 22 from a trusted CIDR range (203.0.113.0/24)

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Note: google_compute_network and google_compute_firewall resources do not support resource labels in GCP.
resource "google_compute_network" "vpc" {
  name                    = "custom-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_firewall" "allow_ssh_trusted" {
  name        = "allow-ssh-trusted"
  network     = google_compute_network.vpc.name
  description = "Allow inbound TCP port 22 access restricted to 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]
}

# Single self-contained Terraform configuration for Cloud Router and Cloud NAT in asia-south1.
# Note: google_compute_network, google_compute_subnetwork, google_compute_router,
# and google_compute_router_nat do not support resource labels in the GCP Compute Engine API.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated VPC network for private workload communication
resource "google_compute_network" "vpc" {
  name                    = "vpc-asia-south1"
  auto_create_subnetworks = false
}

# Regional subnetwork for private VMs
resource "google_compute_subnetwork" "private_subnet" {
  name                     = "sb-asia-south1-private"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = "10.10.0.0/24"
  private_ip_google_access = true
}

# Cloud Router in asia-south1
resource "google_compute_router" "router" {
  name    = "cr-asia-south1"
  region  = "asia-south1"
  network = google_compute_network.vpc.id
}

# Cloud NAT enabling outbound internet access for private VMs without public IPs
resource "google_compute_router_nat" "nat" {
  name                               = "nat-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

