# Note: google_compute_global_address does not support the 'labels' argument
# in the Compute Engine API / Google provider schema; organizational tracking
# is reflected via the resource name and description.
resource "google_compute_global_address" "default" {
  name         = "global-static-ip-dev"
  description  = "Reserved global static external IP address for HTTP(S) load balancing (env: dev)"
  address_type = "EXTERNAL"
  ip_version   = "IPV4"
}

output "ip_address" {
  description = "The reserved global static external IP address"
  value       = google_compute_global_address.default.address
}

