    }
  }
}

provider "google" {
  region = "asia-south1"
  zone   = "asia-south1-a"
}

# Dedicated service account for the Compute Engine VM
resource "google_service_account" "vm_sa" {
  account_id   = "vm-dedicated-sa"
  display_name = "Dedicated Service Account for Internal VM"
}

# Compute Engine VM without an external IP address
resource "google_compute_instance" "internal_vm" {
  name         = "internal-workload-vm"
  machine_type = "e2-medium"
  zone         = "asia-south1-a"

  labels = {
    environment = "dev"
  }

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      labels = {
        environment = "dev"
      }
    }
  }

  network_interface {
    network = "default"
    # access_config is omitted to ensure no external IP is assigned
  }

  service_account {
    email  = google_service_account.vm_sa.email
    scopes = ["cloud-platform"]
  }
}

