# Single Terraform configuration for Google Cloud Pub/Sub with dead-letter topic

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

data "google_project" "current" {}

# Main topic to receive incoming messages
resource "google_pubsub_topic" "main" {
  name = "main-topic"

  labels = {
    environment = "prod"
  }
}

# Dead-letter topic to receive messages that fail processing
resource "google_pubsub_topic" "dead_letter" {
  name = "main-dead-letter-topic"

  labels = {
    environment = "prod"
  }
}

# Subscription with dead-letter policy configured to give up after 5 delivery attempts
resource "google_pubsub_subscription" "main" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  labels = {
    environment = "prod"
  }

  depends_on = [
    google_pubsub_topic_iam_member.dead_letter_publisher,
    google_pubsub_subscription_iam_member.main_subscriber,
  ]
}

# Grant Cloud Pub/Sub service agent permission to publish to the dead-letter topic
resource "google_pubsub_topic_iam_member" "dead_letter_publisher" {
  topic  = google_pubsub_topic.dead_letter.name
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:service-${data.google_project.current.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Grant Cloud Pub/Sub service agent permission to acknowledge messages on the main subscription
resource "google_pubsub_subscription_iam_member" "main_subscriber" {
  subscription = "main-subscription"
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:service-${data.google_project.current.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

