# Input variable for tracking resource environment (mandatory per org policy)
variable "environment" {
  type        = string
  description = "Deployment environment (e.g., dev, staging, prod)"
  default     = "prod"
}

# Input variable for authorized office IP CIDR block
# Policy strictly rejects 0.0.0.0/0 ingress; access must be scoped to specific office IP ranges
variable "office_ip_cidr" {
  type        = string
  description = "Office VPN public IP range in CIDR notation allowed to reach Cloud SQL"
  default     = "203.0.113.0/24"
}

# Random suffix for the instance name to avoid collisions upon recreation
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

resource "google_sql_database_instance" "mysql" {
  name             = "mysql-${var.environment}-${random_id.db_name_suffix.hex}"
  database_version = "MYSQL_8_0"
  region           = "asia-south1"

  # Retain storage per organizational data protection policy
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    # Mandatory organizational tracking labels
    user_labels = {
      environment = var.environment
    }

    ip_configuration {
      # Public IPv4 explicitly requested for office VPN connectivity
      ipv4_enabled = true

      # Restricted to the office VPN network; never 0.0.0.0/0 per organizational policy
      authorized_networks {
        name  = "office-vpn"
        value = var.office_ip_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }
  }
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance"
  value       = google_sql_database_instance.mysql.public_ip_address
}

