# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "project_id" {
  description = "The GCP project ID to host the cluster in."
  type        = string
}

variable "region" {
  description = "The GCP region for the cluster and networking resources."
  type        = string
  default     = "asia-south1"
}

variable "environment" {
  description = "Environment identifier (e.g. dev, staging, prod)."
  type        = string
  default     = "prod"
}

variable "cluster_name" {
  description = "The name of the GKE cluster."
  type        = string
  default     = "private-gke-cluster"
}

# ------------------------------------------------------------------------------
# Networking (VPC-Native Cluster Prerequisite for Private GKE)
# ------------------------------------------------------------------------------

resource "google_compute_network" "gke_vpc" {
  name                    = "${var.cluster_name}-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "${var.cluster_name}-subnet"
  region                   = var.region
  network                  = google_compute_network.gke_vpc.id
  ip_cidr_range            = "10.10.0.0/20"
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# ------------------------------------------------------------------------------
# Least-Privilege GKE Node Service Account
# ------------------------------------------------------------------------------

resource "google_service_account" "gke_nodes" {
  account_id   = "${var.cluster_name}-nodes-sa"
  display_name = "GKE Node Pool Service Account"
}

# Assign standard minimal node roles (least privilege; avoid roles/owner or roles/editor)
resource "google_project_iam_member" "node_log_writer" {
  project = var.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_metric_writer" {
  project = var.project_id
  role    = "roles/monitoring.metricWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_monitoring_viewer" {
  project = var.project_id
  role    = "roles/monitoring.viewer"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# ------------------------------------------------------------------------------
# GKE Cluster
# ------------------------------------------------------------------------------

resource "google_container_cluster" "primary" {
  name     = var.cluster_name
  location = var.region

  network    = google_compute_network.gke_vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  # Manage node pools separately; delete default pool immediately after creation
  remove_default_node_pool = true
  initial_node_count       = 1

  # VPC-native routing configuration for pods and services
  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  # Private cluster configuration (nodes have no public IP addresses)
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity for secure GCP API access from pods
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  # Use regular release channel for managed lifecycle upgrades
  release_channel {
    channel = "REGULAR"
  }

  # Mandatory organisational resource labels
  resource_labels = {
    environment = var.environment
  }

  deletion_protection = false
}

# ------------------------------------------------------------------------------
# GKE Node Pool
# ------------------------------------------------------------------------------

resource "google_container_node_pool" "primary_nodes" {
  name       = "${var.cluster_name}-node-pool"
  cluster    = google_container_cluster.primary.id
  location   = var.region
  node_count = 2

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.gke_nodes.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Kubernetes labels on nodes
    labels = {
      environment = var.environment
    }

    # Metadata configuration recommended for Workload Identity
    workload_metadata_config {
      mode = "GKE_METADATA"
    }
  }
}

