# Terraform configuration for a public static website Cloud Storage bucket.

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "bucket_name" {
  type        = string
  description = "Globally unique name for the static website GCS bucket."
  default     = "public-static-website-asia-south1-example"
}

variable "environment" {
  type        = string
  description = "Deployment environment label."
  default     = "prod"
}

resource "google_storage_bucket" "static_website" {
  name     = var.bucket_name
  location = "asia-south1"

  # Uniform bucket-level access is standard best practice
  uniform_bucket_level_access = true

  # Static website configuration
  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  # Mandatory organizational retention requirement: explicit retention declared via versioning
  versioning {
    enabled = true
  }

  # Mandatory organizational label requirement
  labels = {
    environment = var.environment
  }
}

# Public read access explicitly requested for public static website hosting
resource "google_storage_bucket_iam_member" "public_read" {
  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "google" {
  region = var.region
}

variable "region" {
  type        = string
  description = "GCP region for regional resources (default is the organizational standard asia-south1)."
  default     = "asia-south1"
}

variable "environment" {
  type        = string
  description = "Deployment environment label (dev, staging, prod)."
  default     = "dev"
}

variable "office_vpn_cidr" {
  type        = string
  description = "CIDR range of the office VPN allowed to access the Cloud SQL public IP. Must not be 0.0.0.0/0."
  default     = "198.51.100.0/24" # Example corporate CIDR block; override with actual office VPN external IP range
}

resource "random_id" "db_suffix" {
  byte_length = 4
}

resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-instance-${random_id.db_suffix.hex}"
  region              = var.region
  database_version    = "MYSQL_8_0"
  deletion_protection = true

  settings {
    tier              = "db-n1-standard-1"
    availability_type = "ZONAL"

    user_labels = {
      environment = var.environment
    }

    backup_configuration {
      enabled    = true
      start_time = "02:00"
    }

    ip_configuration {
      # Public IP requested due to office VPN constraints preventing Cloud SQL Auth Proxy usage
      ipv4_enabled = true

      # Restrict authorized networks specifically to the office VPN; do not use 0.0.0.0/0
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }
  }
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

# Terraform configuration for a private Cloud DNS managed zone
# restricted to a specific VPC network.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated VPC network associated with the private DNS zone
resource "google_compute_network" "internal_network" {
  name                    = "vpc-internal"
  auto_create_subnetworks = false
}

# Private Cloud DNS managed zone for internal.example.com.
resource "google_dns_managed_zone" "internal_example_com" {
  name        = "internal-example-com"
  dns_name    = "internal.example.com."
  description = "Private DNS managed zone visible only to internal VPC"
  visibility  = "private"

  labels = {
    environment = "prod"
  }

  private_visibility_config {
    networks {
      network_url = google_compute_network.internal_network.id
    }
  }
}
